<script setup lang="ts">
/**
 * Trail of links from the root to the current page (`design/components/breadcrumbs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/breadcrumbs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, agentPress, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/breadcrumbs.module.css'
import Button from '../controls/Button.vue'
import Menu from '../overlays/Menu.vue'

export interface BreadcrumbItem {
  label: string
  href?: string
  onSelect?: () => void
}

export interface BreadcrumbsProps {
  /**
   * Opens the overflow on mount, for galleries and tests only.
   */
  defaultOpen?: boolean
  /**
   * The last item is the current page; its `href`/`onSelect` are ignored.
   */
  items: BreadcrumbItem[]
  /**
   * The landmark's accessible name, default `Breadcrumb`; localized hosts pass their own.
   */
  label?: string
  /**
   * Above this count, shows the first crumb, overflow and last two; `Infinity` disables it.
   */
  maxItems?: number
  /**
   * The overflow control's accessible name, default `Show path`.
   */
  overflowLabel?: string
}

defineOptions({ name: 'Breadcrumbs', inheritAttrs: false })

const props = withDefaults(defineProps<BreadcrumbsProps>(), {
  defaultOpen: undefined,
  label: 'Breadcrumb',
  maxItems: 4,
  overflowLabel: 'Show path',
})
const emit = defineEmits<{ navigate: [href: string] }>()
const listening = useListening()
const root = useTemplateRef<HTMLElement>('root')
const collapsed = computed(() => props.items.length > props.maxItems)
const row = computed(() =>
  collapsed.value
    ? [...props.items.slice(0, 1), null, ...props.items.slice(1).slice(-2)]
    : props.items,
)
const last = computed(() => row.value.length - 1)
const hidden = computed(() =>
  collapsed.value
    ? props.items.slice(1, -2).map((item) => ({
        label: item.label,
        onSelect: () => {
          if (item.onSelect) item.onSelect()
          else if (item.href !== undefined) {
            if (listening.navigate) emit('navigate', item.href)
            else window.location.assign(item.href)
          }
        },
      }))
    : [],
)
const navigatesHere = computed(
  () =>
    (event: MouseEvent): boolean =>
      !event.defaultPrevented &&
      event.button === 0 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.shiftKey &&
      !event.altKey,
)
const route = computed(() => (event: MouseEvent, href: string | undefined): void => {
  if (href === undefined || !listening.navigate || !navigatesHere.value(event)) return
  event.preventDefault()
  emit('navigate', href)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Breadcrumbs',
    element: () => root.value,
    state: () => ({
      items: props.items
        .filter((item, at) => props.items.findIndex((other) => other.label === item.label) === at)
        .map((item) => ({
          id: item.label,
          label: item.label,
          ...(item === props.items[props.items.length - 1] ||
          (item.href === undefined && item.onSelect === undefined)
            ? { disabled: true }
            : {}),
        })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            const item = props.items.find((candidate) => candidate.label === value)
            if (item === undefined) return
            const shown = row.value.indexOf(item)
            if (shown === -1) hidden.value.find((entry) => entry.label === value)?.onSelect()
            else
              agentPress(
                root.value?.querySelectorAll(':scope > ol > li')[shown]?.querySelector('a, button'),
              )
          })(),
      },
    },
    withholds: () =>
      hidden.value.length === 0 ? null : root.value?.querySelectorAll(':scope > ol > li')[1],
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <nav ref="root" :class="styles.nav" :aria-label="label" data-member="breadcrumbs">
    <!-- list -->
    <ol :class="styles.list">
      <template v-for="(rung, at) in row" :key="rung === null ? 'overflow' : `${at}-${rung.label}`">
        <!-- item -->
        <li :class="styles.item">
          <Menu v-if="rung === null" :defaultOpen="defaultOpen" :items="hidden">
            <template #trigger>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                :iconOnly="true"
                icon="overflow"
                :label="overflowLabel"
              />
            </template>
          </Menu>
          <span v-else-if="at === last" :class="styles.crumb" aria-current="page">
            {{ rung.label }}
          </span>
          <a
            v-else-if="rung.href !== undefined"
            :class="styles.crumb"
            :href="rung.href"
            @click="(rung.onSelect?.(), route($event, rung.href))"
          >
            {{ rung.label }}
          </a>
          <button
            v-else-if="rung.onSelect !== undefined"
            :class="styles.crumb"
            type="button"
            @click="rung.onSelect?.()"
          >
            {{ rung.label }}
          </button>
          <span v-else :class="styles.crumb">
            {{ rung.label }}
          </span>
          <!-- separator -->
          <span v-if="at !== last" :class="styles.separator">
            <Icon name="next" size="sm" />
          </span>
        </li>
      </template>
    </ol>
  </nav>
</template>
